CHALLENGE:

Can you make 3 LEDs light up one-by-one from left to right to left, using an array?

Hints:
Create array of LED pins
No need for #defines of the pins
Set pin mode of LED pins
Use “for” loop to turn LED on, delay, turn LED off
Check your IDEfor the newchallenge!
int ledPins[_] = {_, _, _}; // change these to whatever pins your LEDs are on

void setup() { 
  for (int i = _; i < _; i__) { 
    pinMode(_, _); 
  } 
} 

void loop() { 
  // left to right 
  for (int i = _; i < _; i__) { 
    digitalWrite(ledPins[i], __); 
    delay(200); 
    digitalWrite(ledPins[i], __); 
  } 
  // right to left 
  for (int i = _; i >= _; i__) { 
    digitalWrite(ledPins[i], __); 
    delay(200); 
    digitalWrite(ledPins[i], __); 
  } 
}
ANSWER
int ledPins[3] = {2, 3, 4}; // change these to whatever pins your LEDs are on

void setup() { 
  for (int i = 0; i < 3; i++) { 
    pinMode(ledPins[i], OUTPUT); 
  } 
} 

void loop() { 
  // left to right 
  for (int i = 0; i < 3; i++) { 
    digitalWrite(ledPins[i], HIGH); 
    delay(200); 
    digitalWrite(ledPins[i], LOW); 
  } 
  // right to left 
  for (int i = 2; i >= 0; i--) { 
    digitalWrite(ledPins[i], HIGH); 
    delay(200); digitalWrite(ledPins[i], LOW); 
  } 
}
