CHALLENGE:

Can you make 3 Servos move one-by-one, using an array?

Create array of Servo Pins
Create array of Servos
Attach servos to pins
In setup(): Use “for” loop to initialize servos (set to zero)
In loop():   Use “for” loop to move servo, delay, move it back, delay
Check your IDEfor the newchallenge!
#include <Servo.h>

int servoPins[_] = {_, _, _};   // array of Servo pins
Servo servos[_];                  // array of Servos

void setup() {  
  for (int i = _; i < _; i__) {    
    servos__.attach(servoPins__); // attach servos to pins    
    servos__.write(0);             // initialize servos, set to zero    
    delay(500);                     // allow time for servo to move  
  }
}

void loop() {  
  for (int i = _; i < _; i__) {    
    servos__.write(90);   // move servo    
    delay(500);            // delay    
    servos__.write(0);    // move it back    
    delay(500);            // delay  
  }
}
ANSWER
#include <Servo.h>

int servoPins[3] = {9, 10, 11};   // array of Servo pins
Servo servos[3];                  // array of Servos

void setup() {  
  for (int i = 0; i < 3; i++) {    
    servos[i].attach(servoPins[i]); // attach servos to pins    
    servos[i].write(0);             // initialize servos, set to zero    
    delay(500);                     // allow time for servo to move  
  }
}

void loop() {  
  for (int i = 0; i < 3; i++) {    
    servos[i].write(90);   // move servo    
    delay(500);            // delay    
    servos[i].write(0);    // move it back    
    delay(500);            // delay  
  }
}
