CHALLENGE:

Can you make your name scroll across the display?

Include the library
In setup(): initialize the display
In loop(): A “for” loop runs from 16 down to zero.  Index is used as cursor position on display.  Include a delay to make it “scroll”.
Can you make it move right to left, then left to right?
Check your IDEfor the newchallenge!
#include <LiquidCrystal.h>  // DO NOT CHANGE THIS LIBRARY CALL

// adjust these to match your wiring
LiquidCrystal lcd(12, 11, 5, 4, 3, 2); // rs, en, d4, d5, d6, d7

String myName = “John Doe"; // swap this for your own name

void setup() {  
  lcd.begin(_,_); // initialize the display
}

void loop() {  
// right to left  
  for (int i = _; i >= _; i__) {    
    lcd.clear();    
    lcd.setCursor(_, 0); // index used as cursor position    
    lcd.print(__);    
    delay(200); // delay to create the scroll effect  
  }  
// left to right  
  for (int i = _; i <= _; i__) {    
    lcd.clear();    
    lcd.setCursor(_, 0);    
    lcd.print(__);    
    delay(200);  
  }
}
ANSWER
#include <LiquidCrystal.h>  // include the library

// adjust these to match your wiring
LiquidCrystal lcd(12, 11, 5, 4, 3, 2); // rs, en, d4, d5, d6, d7

String myName = “John Doe"; // swap this for your own name

void setup() {  
  lcd.begin(16, 2); // initialize the display (16 cols, 2 rows)
}

void loop() {  
// right to left  
  for (int i = 16; i >= 0; i--) {    
    lcd.clear();    
    lcd.setCursor(i, 0); // index used as cursor position    
    lcd.print(myName);    
    delay(200); // delay to create the scroll effect  
  }  
// left to right  
  for (int i = 0; i <= 16; i++) {    
    lcd.clear();    
    lcd.setCursor(i, 0);    
    lcd.print(myName);    
    delay(200);  
  }
}
